pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Penalize small post-residuals more heavily near the end of the stream
    score -= 0.15 * (1.0 - stream_progress) * post_residual.powi(2);

    // Reward larger bin capacities with a logarithmic scale to emphasize the benefits of larger capacities
    score += 0.1 * (bin_capacity as f64).ln() / (bin_capacity as f64 + 10.0);

    // Penalize empty bins at the start of the stream more harshly
    if step_index == 0 && post_residual == 0 {
        score -= 20.0;
    }

    // Reward fitting bins with a higher multiplier to encourage the use of existing bins
    if fitting_bins_count == 1 {
        score += 3.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // Penalize items that are significantly larger than the next item in the stream
    if item_size > next_item_size * 2 {
        score -= 1.0;
    }

    // Reward bins with a mean residual close to zero
    if mean_residual < 5.0 {
        score += 0.5 * (1.0 - mean_residual / 5.0);
    }

    score
