pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Favor bins with more remaining capacity
    score += ((bin_capacity - bin_residual) as f64 / bin_capacity as f64).powi(2) * 15.0;

    // Penalize creating new bins if possible
    if fitting_bins_count > 0 {
        score -= 3.5;
    }

    // Favor bins with lower mean residual to balance load across bins
    score += mean_residual * 0.85;

    // Reward items that fit exactly in the current bin (zero waste)
    if post_residual == 0 {
        score += 28.0;
    }

    // Penalize large items when there are few fitting bins left
    if item_size > 40 && fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Favor bins with a smaller next item to allow for better packing
    if next_item_size < item_size {
        score += (item_size - next_item_size) as f64 / item_size as f64 * 3.0;
    }

    // Penalize consecutive items being larger than the current bin capacity
    if step_index > 0 && item_size + next_item_size > bin_capacity {
        score -= 12.0;
    }

    // Reward bins with a higher density of items (less waste)
    let density = total_items as f64 / open_bins_count as f64;
    score += density * 5.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
